/* Differential test of checker/rt/tmpl_cmp.c (cq-w0-tmpl-cmp) against native x86-64 code.
 *
 * native.ll (generated by difftest.py) holds one function per (op, width): the same LLVM IR
 * operation, compiled by clang-19 -O1, operands and result passed through memory. table.inc lists
 * them. For every entry the harness runs the family's registered cqe_op_fn on the same operands
 * and compares bit patterns. Inputs per width: edge values, a seeded random set (uniform and with
 * random bit length), every input when the operands total at most 16 bits, fp specials for the fp
 * arms of select. Every call is also repeated with garbage above bit W (and one extra word) in
 * every operand, which must not change the result (CR §1.2: only the low W bits are read).
 * CR §2's abs(INT_MIN) = INT_MIN is checked against the table as well as native.
 *
 * The family is linked directly; cqe_register_op and cqe_fail are mocked here, so the test does
 * not depend on the core. */
#include <stdarg.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "cqe.h"

/* ---- mocks of the core ---- */

#define MAXOPS 64
static struct { char op[24]; cqe_op_fn fn; } reg[MAXOPS];
static int nreg;
static int nfail_calls;
static int quiet_fail;

void cqe_register_op(const char *op, cqe_op_fn fn) {
  for (int i = 0; i < nreg; ++i)
    if (!strcmp(reg[i].op, op)) {
      fprintf(stderr, "FAIL: op %s registered twice\n", op);
      exit(2);
    }
  if (nreg == MAXOPS) exit(3);
  snprintf(reg[nreg].op, sizeof reg[nreg].op, "%s", op);
  reg[nreg++].fn = fn;
}

void cqe_fail(const char *fmt, ...) {
  ++nfail_calls;
  if (quiet_fail) return;
  va_list ap;
  va_start(ap, fmt);
  fprintf(stderr, "cqe_fail: ");
  vfprintf(stderr, fmt, ap);
  fprintf(stderr, "\n");
  va_end(ap);
}

static cqe_op_fn lookup(const char *op) {
  for (int i = 0; i < nreg; ++i)
    if (!strcmp(reg[i].op, op)) return reg[i].fn;
  return NULL;
}

/* ---- the generated table ---- */

typedef void (*native_fn)(const uint64_t *a, const uint64_t *b, const uint64_t *c, uint64_t *o);
typedef struct {
  const char *op, *pred, *w; /* template op, icmp predicate or "", operand width */
  char kind;                 /* 'i' or 'f' (operand kind) */
  unsigned bits;             /* W */
  int nargs;                 /* data operands of the template (select: 3, cond first) */
  unsigned rbits;            /* result width */
  native_fn fn;
} entry_t;

#include "table.inc"

/* ---- values ---- */

#define MAXW 8 /* words per operand buffer: up to 512 bits, with one spare */

typedef struct { uint64_t w[MAXW]; } val_t;

static uint64_t rng_state = 0x9E3779B97F4A7C15ull; /* fixed seed */
static uint64_t rnd(void) {
  uint64_t x = rng_state;
  x ^= x << 13; x ^= x >> 7; x ^= x << 17;
  return rng_state = x;
}

static unsigned nwords(unsigned bits) { return (bits + 63) / 64; }
static void mask(val_t *v, unsigned bits) {
  unsigned nw = nwords(bits);
  for (unsigned i = nw; i < MAXW; ++i) v->w[i] = 0;
  if (bits % 64) v->w[nw - 1] &= (1ull << (bits % 64)) - 1;
}
static void setbit(val_t *v, unsigned i) { v->w[i / 64] |= 1ull << (i % 64); }

static val_t vzero(void) { val_t v; memset(&v, 0, sizeof v); return v; }
static val_t vones(unsigned bits) { val_t v; memset(&v, 0xff, sizeof v); mask(&v, bits); return v; }
static val_t vsmall(uint64_t x, unsigned bits) { val_t v = vzero(); v.w[0] = x; mask(&v, bits); return v; }
static val_t vmin(unsigned bits) { val_t v = vzero(); setbit(&v, bits - 1); return v; }
static val_t vmax(unsigned bits) { val_t v = vones(bits); v.w[(bits - 1) / 64] &= ~(1ull << ((bits - 1) % 64)); mask(&v, bits); return v; }
static val_t vadd1(val_t v, unsigned bits, int d) { /* v + d, d = +-1, mod 2^W */
  for (unsigned i = 0; i < MAXW; ++i) {
    uint64_t o = v.w[i];
    v.w[i] += (uint64_t)(int64_t)d;
    if (d > 0 ? v.w[i] > o : v.w[i] < o) break;
  }
  mask(&v, bits);
  return v;
}
static val_t vrand(unsigned bits) { val_t v; for (unsigned i = 0; i < MAXW; ++i) v.w[i] = rnd(); mask(&v, bits); return v; }
static val_t vrand_len(unsigned bits) { /* random value of random bit length, random sign */
  unsigned len = (unsigned)(rnd() % (bits + 1));
  val_t v = vrand(bits);
  if (len == 0) v = vzero();
  else if (len < bits) mask(&v, len);
  if (rnd() & 1) { /* negate */
    for (unsigned i = 0; i < MAXW; ++i) v.w[i] = ~v.w[i];
    v = vadd1(v, bits, 1);
  }
  mask(&v, bits);
  return v;
}

#define MAXVALS 128
typedef struct { val_t v[MAXVALS]; int n; } vset_t;
static void push(vset_t *s, val_t v) { if (s->n < MAXVALS) s->v[s->n++] = v; }

static void edge_values(vset_t *s, unsigned bits) {
  s->n = 0;
  push(s, vzero());
  push(s, vsmall(1, bits));
  push(s, vones(bits));                 /* -1 */
  push(s, vmin(bits));                  /* INT_MIN */
  push(s, vmax(bits));                  /* INT_MAX */
  push(s, vsmall(2, bits));
  push(s, vadd1(vmin(bits), bits, 1));  /* INT_MIN + 1 */
  push(s, vadd1(vmax(bits), bits, -1)); /* INT_MAX - 1 */
  push(s, vadd1(vones(bits), bits, -1)); /* -2 */
  if (bits > 64) { /* word boundaries: carries and borrows across words */
    val_t a = vzero(); a.w[0] = ~0ull; push(s, a);
    val_t b = vzero(); b.w[1] = 1; mask(&b, bits); push(s, b);
    val_t c = vones(bits); c.w[0] = 0; push(s, c);
  }
  if (bits >= 4) { /* half-range boundaries: products around 2^W */
    val_t h = vzero(); setbit(&h, bits / 2); push(s, h);
    push(s, vadd1(h, bits, -1));
  }
}

/* fp bit patterns: +-0, +-Inf, qNaN, sNaN, NaN with payload, -NaN, subnormals, normals. */
static void fp_specials(vset_t *s, unsigned bits) {
  s->n = 0;
  if (bits == 80) { /* x87: 64-bit significand with explicit integer bit, 15-bit exponent */
    const uint64_t I = 1ull << 63, Q = 1ull << 62;
    struct { uint64_t m; uint16_t se; } p[] = {
        {0, 0}, {0, 0x8000}, {I, 0x7fff}, {I, 0xffff},           /* +-0, +-Inf */
        {I | Q, 0x7fff}, {I | Q, 0xffff}, {I | 1, 0x7fff},       /* qNaN, -qNaN, sNaN */
        {I | Q | 0x1234, 0x7fff}, {1, 0}, {I - 1, 0x8000},        /* payload NaN, subnormals */
        {I, 1}, {~0ull, 0x7ffe}, {I, 0x3fff}, {I, 0xbfff},       /* min normal, max, 1, -1 */
        {Q, 0x7fff}, {0, 0x7fff}, {Q, 0x3fff}, {I, 0},           /* pseudo-NaN, pseudo-Inf, unnormal, pseudo-denormal */
    };
    for (size_t i = 0; i < sizeof p / sizeof p[0]; ++i) {
      val_t v = vzero(); v.w[0] = p[i].m; v.w[1] = p[i].se; push(s, v);
    }
    return;
  }
  unsigned mb = bits == 16 ? 10 : bits == 32 ? 23 : 52, eb = bits - 1 - mb;
  uint64_t sign = 1ull << (bits - 1), expall = ((1ull << eb) - 1) << mb, qbit = 1ull << (mb - 1);
  uint64_t one = ((1ull << (eb - 1)) - 1) << mb;
  uint64_t p[] = {0, sign, expall, sign | expall, expall | qbit, sign | expall | qbit, expall | 1,
                  expall | qbit | 0x15, 1, qbit | (qbit - 1), 1ull << mb, expall - 1, one, sign | one};
  for (size_t i = 0; i < sizeof p / sizeof p[0]; ++i) push(s, vsmall(p[i], bits));
}

/* ---- running one case ---- */

static long ncases, nmismatch;

static void to_cqe(cqe_val *cv, val_t *v, unsigned bits, char kind, unsigned nw) {
  cv->bits = bits; cv->kind = kind; cv->nw = nw; cv->w = v->w;
}

static void report(const entry_t *e, const char *what, const val_t *ops, int nops, const uint64_t *want,
                   const uint64_t *got, unsigned rw) {
  if (nmismatch++ > 40) return;
  fprintf(stderr, "MISMATCH %s %s%s%s %s:", what, e->op, e->pred[0] ? "_" : "", e->pred, e->w);
  for (int i = 0; i < nops; ++i) {
    fprintf(stderr, " op%d=", i);
    for (int k = (int)nwords(e->bits) - 1; k >= 0; --k) fprintf(stderr, "%016llx", (unsigned long long)ops[i].w[k]);
  }
  fprintf(stderr, " native=");
  for (int k = (int)rw - 1; k >= 0; --k) fprintf(stderr, "%016llx", (unsigned long long)want[k]);
  fprintf(stderr, " ours=");
  for (int k = (int)rw - 1; k >= 0; --k) fprintf(stderr, "%016llx", (unsigned long long)got[k]);
  fprintf(stderr, "\n");
}

/* ops: data operands in template order (select: cond, arm1, arm2). */
static void run_case(const entry_t *e, cqe_op_fn fn, val_t *ops) {
  int n = e->nargs;
  unsigned W = e->bits;
  /* native: (a, b, c) = data operands in order; select's native signature is (cond, t, f) too. */
  val_t in[3], out = vzero();
  for (int i = 0; i < 3; ++i) in[i] = i < n ? ops[i] : vzero();
  for (int i = 0; i < n; ++i) mask(&in[i], (!strcmp(e->op, "select") && i == 0) ? 1 : W);
  e->fn(in[0].w, in[1].w, in[2].w, out.w);
  mask(&out, e->rbits);
  unsigned rw = nwords(e->rbits);

  cqe_tname t;
  memset(&t, 0, sizeof t);
  snprintf(t.op, sizeof t.op, "%s", e->op);
  snprintf(t.pred, sizeof t.pred, "%s", e->pred);
  snprintf(t.w, sizeof t.w, "%s", e->w);

  for (int garbage = 0; garbage < 2; ++garbage) {
    val_t a[3];
    cqe_val cv[3];
    for (int i = 0; i < n; ++i) {
      int is_cond = !strcmp(e->op, "select") && i == 0;
      unsigned bi = is_cond ? 1 : W;
      a[i] = in[i];
      unsigned nw = nwords(bi);
      if (garbage) { /* set every bit above bi and add one extra word of junk */
        val_t j = vrand(MAXW * 64 - 1);
        for (unsigned b = bi; b < (nw + 1) * 64; ++b)
          if ((j.w[b / 64] >> (b % 64)) & 1) setbit(&a[i], b);
        nw += 1;
      }
      to_cqe(&cv[i], &a[i], bi, is_cond ? 'i' : e->kind, nw);
    }
    uint64_t ow[MAXW + 1];
    for (unsigned k = 0; k <= MAXW; ++k) ow[k] = 0xA5A5A5A5A5A5A5A5ull; /* stale content must be overwritten */
    cqe_val o = {0, 0, rw + garbage, ow};
    int f0 = nfail_calls;
    int rc = fn(&t, cv, n, &o);
    ++ncases;
    int bad = rc != 0 || nfail_calls != f0 || o.bits != e->rbits ||
              o.kind != (e->rbits == W && strcmp(e->op, "icmp") ? e->kind : 'i');
    for (unsigned k = 0; k < rw + garbage; ++k)
      if (ow[k] != (k < rw ? out.w[k] : 0)) bad = 1;
    if (bad) report(e, garbage ? "(garbage above W)" : "", in, n, out.w, ow, rw + garbage);
  }
}

static void run_entry(const entry_t *e) {
  cqe_op_fn fn = lookup(e->op);
  if (!fn) {
    fprintf(stderr, "FAIL: op %s not registered\n", e->op);
    ++nmismatch;
    return;
  }
  unsigned W = e->bits;
  int sel = !strcmp(e->op, "select");
  int ndata = sel ? 2 : e->nargs; /* operands drawn from the value sets (select: the arms) */
  long before = ncases;
  vset_t E;
  if (e->kind == 'f') fp_specials(&E, W);
  else edge_values(&E, W);
  val_t ops[3];

#define RUN(...)                                              \
  do {                                                        \
    if (sel) for (int c = 0; c < 2; ++c) {                    \
      val_t xs[2] = {__VA_ARGS__};                            \
      ops[0] = vsmall((uint64_t)c, 1); ops[1] = xs[0]; ops[2] = xs[1]; \
      run_case(e, fn, ops);                                   \
    } else {                                                  \
      val_t xs[2] = {__VA_ARGS__};                            \
      ops[0] = xs[0]; ops[1] = xs[1];                         \
      run_case(e, fn, ops);                                   \
    }                                                         \
  } while (0)

  /* exhaustive when the data operands total at most 16 bits (select's cond is one more bit) */
  if (e->kind == 'i' && W * (unsigned)ndata <= 16) {
    uint64_t lim = 1ull << W;
    if (ndata == 1) for (uint64_t x = 0; x < lim; ++x) RUN(vsmall(x, W), vzero());
    else for (uint64_t x = 0; x < lim; ++x) for (uint64_t y = 0; y < lim; ++y) RUN(vsmall(x, W), vsmall(y, W));
  }
  /* edge values (fp specials for fp arms), all pairs */
  if (ndata == 1) for (int i = 0; i < E.n; ++i) RUN(E.v[i], vzero());
  else for (int i = 0; i < E.n; ++i) for (int j = 0; j < E.n; ++j) RUN(E.v[i], E.v[j]);
  /* seeded random: uniform, random bit length, and mixed with edges */
  for (int r = 0; r < 3000; ++r) {
    val_t x = (r & 1) ? vrand_len(W) : vrand(W), y = (r & 2) ? vrand_len(W) : vrand(W);
    if (e->kind == 'f' && (r % 3) == 0) { x = E.v[rnd() % E.n]; }
    RUN(x, y);
    if (ndata == 2) { RUN(E.v[r % E.n], y); RUN(x, E.v[r % E.n]); }
  }
  /* x == y */
  for (int r = 0; r < 200; ++r) { val_t x = vrand_len(W); RUN(x, x); }
  printf("  %-14s %-3s %-5s %8ld cases\n", e->op, e->pred, e->w, ncases - before);
}

/* CR §2 rows this family covers, checked against the table itself. */
static void table_rows(void) {
  static const unsigned widths[] = {1, 7, 8, 16, 32, 64, 100, 128, 256};
  for (size_t i = 0; i < sizeof widths / sizeof widths[0]; ++i) {
    unsigned W = widths[i];
    char ws[8];
    snprintf(ws, sizeof ws, "i%u", W);
    cqe_tname t; memset(&t, 0, sizeof t);
    snprintf(t.op, sizeof t.op, "abs"); snprintf(t.w, sizeof t.w, "%s", ws);
    val_t m = vmin(W);
    cqe_val a = {W, 'i', nwords(W), m.w};
    uint64_t ow[MAXW] = {0};
    cqe_val o = {0, 0, nwords(W), ow};
    int rc = lookup("abs")(&t, &a, 1, &o);
    ++ncases;
    if (rc || memcmp(ow, m.w, nwords(W) * 8)) { fprintf(stderr, "FAIL: CR §2 abs(INT_MIN) at %s\n", ws); ++nmismatch; }
  }
  printf("  CR §2 abs(INT_MIN) = INT_MIN at 9 widths\n");
}

/* The calling convention's error and allocation paths. */
static void convention(void) {
  cqe_tname t; memset(&t, 0, sizeof t);
  val_t x = vsmall(5, 32), y = vsmall(7, 32);
  cqe_val a[3] = {{32, 'i', 1, x.w}, {32, 'i', 1, y.w}, {32, 'i', 1, y.w}};
  int checks = 0;
#define EXPECT_FAIL(setup)                                                 \
  do {                                                                     \
    memset(&t, 0, sizeof t); setup;                                        \
    uint64_t ow[2] = {0}; cqe_val o = {0, 0, 2, ow};                       \
    int f0 = nfail_calls; quiet_fail = 1;                                  \
    int rc = lookup("icmp")(&t, a, nargs, &o);                             \
    quiet_fail = 0; ++checks;                                              \
    if (rc != -1 || nfail_calls != f0 + 1) {                               \
      fprintf(stderr, "FAIL: convention: '%s' not rejected\n", #setup);    \
      ++nmismatch;                                                         \
    }                                                                      \
  } while (0)
  int nargs = 2;
  EXPECT_FAIL((strcpy(t.op, "icmp"), strcpy(t.pred, "xx"), strcpy(t.w, "i32")));
  EXPECT_FAIL((strcpy(t.op, "icmp"), strcpy(t.w, "i32")));                 /* no predicate */
  EXPECT_FAIL((strcpy(t.op, "smax"), strcpy(t.pred, "eq"), strcpy(t.w, "i32")));
  EXPECT_FAIL((strcpy(t.op, "smax"), strcpy(t.w, "f32")));
  EXPECT_FAIL((strcpy(t.op, "smax"), strcpy(t.w, "i0")));
  EXPECT_FAIL((strcpy(t.op, "smax"), strcpy(t.w, "f48")));
  EXPECT_FAIL((strcpy(t.op, "select"), strcpy(t.w, "i32")));               /* arity 2 != 3 */
  EXPECT_FAIL((strcpy(t.op, "smax"), strcpy(t.w, "i32"), strcpy(t.to, "i64")));
  nargs = 3;
  EXPECT_FAIL((strcpy(t.op, "abs"), strcpy(t.w, "i32")));                  /* arity 3 != 1 */
  /* an op outside the family: CQE_OP_NOT_MINE (1), no violation */
  {
    memset(&t, 0, sizeof t); strcpy(t.op, "fcmp"); strcpy(t.pred, "oeq"); strcpy(t.w, "f64");
    uint64_t ow[1]; cqe_val o = {0, 0, 1, ow};
    int f0 = nfail_calls;
    int rc = lookup("icmp")(&t, a, 2, &o);
    ++checks;
    if (rc != 1 || nfail_calls != f0) { fprintf(stderr, "FAIL: convention: foreign op not answered 1\n"); ++nmismatch; }
  }
  /* out too short: a 128-bit result into one word */
  {
    memset(&t, 0, sizeof t); strcpy(t.op, "umax"); strcpy(t.w, "i128");
    uint64_t ow[1]; cqe_val o = {0, 0, 1, ow};
    int f0 = nfail_calls; quiet_fail = 1;
    int rc = lookup("umax")(&t, a, 2, &o);
    quiet_fail = 0; ++checks;
    if (rc != -1 || nfail_calls != f0 + 1) { fprintf(stderr, "FAIL: convention: short out not rejected\n"); ++nmismatch; }
  }
  /* out->w == NULL: allocated, owned by the caller */
  {
    memset(&t, 0, sizeof t); strcpy(t.op, "umax"); strcpy(t.w, "i32");
    cqe_val o = {0, 0, 0, NULL};
    int rc = lookup("umax")(&t, a, 2, &o);
    ++checks;
    if (rc || !o.w || o.nw != 1 || o.w[0] != 7 || o.bits != 32 || o.kind != 'i') { fprintf(stderr, "FAIL: convention: NULL out\n"); ++nmismatch; }
    free(o.w);
  }
  /* an operand with fewer words than W needs reads 0 above them */
  {
    memset(&t, 0, sizeof t); strcpy(t.op, "icmp"); strcpy(t.pred, "eq"); strcpy(t.w, "i128");
    val_t z = vzero(); z.w[1] = 0;
    cqe_val b2[2] = {{128, 'i', 1, x.w}, {128, 'i', 2, z.w}};
    z.w[0] = 5;
    uint64_t ow[1] = {9}; cqe_val o = {0, 0, 1, ow};
    int rc = lookup("icmp")(&t, b2, 2, &o);
    ++checks;
    if (rc || ow[0] != 1) { fprintf(stderr, "FAIL: convention: short operand\n"); ++nmismatch; }
  }
  printf("  calling convention: %d checks\n", checks);
}

int main(void) {
  static const char *ops[] = {"icmp", "select", "smax", "smin", "umax", "umin", "abs",
                              "uadd_overflow", "sadd_overflow", "usub_overflow", "ssub_overflow",
                              "umul_overflow", "smul_overflow", "uadd_sat", "usub_sat"};
  for (size_t i = 0; i < sizeof ops / sizeof ops[0]; ++i)
    if (!lookup(ops[i])) { fprintf(stderr, "FAIL: %s not registered\n", ops[i]); ++nmismatch; }
  if (nreg != (int)(sizeof ops / sizeof ops[0])) { fprintf(stderr, "FAIL: %d ops registered, want 15\n", nreg); ++nmismatch; }
  printf("registered ops: %d\n", nreg);
  size_t ne = sizeof TABLE / sizeof TABLE[0];
  for (size_t i = 0; i < ne; ++i) run_entry(&TABLE[i]);
  table_rows();
  convention();
  printf("entries: %zu  cases: %ld  mismatches: %ld\n", ne, ncases, nmismatch);
  return nmismatch ? 1 : 0;
}
